        {flag.icon === "map" && (
          <svg width="36" height="36" viewBox="0 0 24 24" fill="none">
            <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z" stroke={flag.color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
