const SpreadsheetRow: React.FC<{
  row: (typeof SPREADSHEET_ROWS)[number];
  index: number;
  delay: number;
}> = ({ row, index, delay }) => {
  const frame = useCurrentFrame();
  const { fps: videoFps } = useVideoConfig();
  const progress = spring({ frame, fps: videoFps, delay, config: { damping: 200 } });

  const scoreColor = row.score >= 70 ? COLORS.green : row.score >= 45 ? COLORS.yellow : COLORS.red;
  const isEven = index % 2 === 0;

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "2fr 1fr 1fr 1fr 1.2fr 1fr",
        gap: 0,
        backgroundColor: isEven ? "rgba(255,255,255,0.03)" : "rgba(255,255,255,0.015)",
        borderBottom: "1px solid rgba(255,255,255,0.06)",
        padding: "28px 48px",
        opacity: progress,
        transform: `translateY(${interpolate(progress, [0, 1], [20, 0])}px)`,
